This Terraform configuration creates an AWS ElastiCache Redis user group containing 3 users:

1. A required `default` Redis user with no password authentication.
2. An application user with full Redis command access.
3. A read-only user with read command access.

Passwords for the non-default users are generated securely using the Terraform `random` provider.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the ElastiCache user group will be created."
  type        = string
  default     = "us-east-1"
}

